}

export function formatPythonBytes(bytes) {
  const quote = selectQuote(bytes);
  const quoteCode = quote.charCodeAt(0);
  let body = '';

  for (const value of bytes) {
    if (value === 0x5c) {
      body += '\\\\';
    } else if (value === quoteCode) {
      body += `\\${quote}`;
    } else if (value === 0x09) {
      body += '\\t';
    } else if (value === 0x0a) {
      body += '\\n';
    } else if (value === 0x0d) {
      body += '\\r';
    } else if (value >= 0x20 && value <= 0x7e) {
